// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint64 seq, uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, bytes32 batcherHash, uint256 overhead, uint256 scalar, address actor) public {
        vm.assume(actor != address(0));
        // P never writes sequenceNumber; bug writes it for any caller that passes the depositor check.
        // Route a call from the depositor account so M actually stores seq.
        address depositor = c.depositorAccount();
        vm.prank(depositor);
        c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcherHash, overhead, scalar);
        assertEq(uint256(c.sequenceNumber()), 0);
    }
}
